import { useEffect,useState } from 'react';import { Bar } from 'react-chartjs-2';import { Chart as ChartJS,CategoryScale,LinearScale,BarElement,Tooltip,Legend } from 'chart.js';import { Section } from '../components/Section';import { Seo } from '../components/Seo';import { api } from '../services/api';ChartJS.register(CategoryScale,LinearScale,BarElement,Tooltip,Legend);export function Admin(){const [stats,setStats]=useState({users:0,loans:0,revenue:0,messages:0});useEffect(()=>{api.get('/admin/stats').then(r=>setStats(r.data)).catch(()=>{})},[]);const labels=['Customers','Applications','Revenue','Messages'];return <><Seo title="Admin Dashboard" description="Admin analytics and management console."/><Section><h1 className="text-5xl font-black">Admin Dashboard</h1><div className="mt-8 grid gap-4 md:grid-cols-4">{Object.entries(stats).map(([k,v])=><div className="card" key={k}><p className="capitalize">{k}</p><h2 className="text-3xl font-black">{String(v)}</h2></div>)}</div><div className="card mt-8"><Bar data={{labels,datasets:[{label:'Analytics',data:[stats.users,stats.loans,Number(stats.revenue)/1000,stats.messages],backgroundColor:['#F7C948','#071B4D','#D72638','#64748b']}]}}/></div><div className="mt-8 grid gap-4 md:grid-cols-3">{['Customer Management','Loan Applications','Loan Approval','EMI Management','Payment Reports','User Management','Document Verification','Settings'].map(x=><div className="card font-bold" key={x}>{x}<p className="mt-2 text-sm font-normal">Secure administrative workflow module.</p></div>)}</div></Section></>}
